from lib import *
S = SS('n34')
steps = [
    step("同一个字段名 files 上传了 3 个文件(b.txt、a.png、c.bin),另有 other 字段的 o.txt:c.FormFile(\"files\") 只返回第一个(b.txt,3 字节);c.MultipartForm().File[\"files\"] 返回全部,按请求里的顺序,每个有 Filename、Size 和 Header(Content-Type,没写时是 application/octet-stream);表单里共有 2 个文件字段名;普通字段在 Value 里。字段不存在时 FormFile 返回 http: no such file。", t=tl(S(1)), mark=lidx(S(1), 'FormFile(files) → b.txt 3 字节', 'File["files"] = b.txt(3 字节,text/plain) a.png'), done=lidx(S(1), 'http: no such file'), kv=KV([['FormFile', '只取第一个'], ['MultipartForm().File[name]', '全部,保持请求顺序'], ['不存在', 'http: no such file']], ['FormFile'])),
    step("绑定到结构体:*multipart.FileHeader 字段接单个文件,[]*multipart.FileHeader 接多个(files 只有一个时也是长度 1 的切片);binding:\"required\" 对文件头指针同样有效——缺 avatar 报 Up.Avatar required,缺 title 报 Up.Title required;普通字段、文件字段、校验一次完成。", t=tl(S(2)), mark=lidx(S(2), '缺 avatar', '缺 title'), done=lidx(S(2), '全部给出', 'files 只有一个'), kv=KV([['*multipart.FileHeader', '单个文件'], ['[]*multipart.FileHeader', '多个文件'], ['required', '文件头指针也适用']], ['[]*multipart.FileHeader'])),
    step("客户端给的文件名:Go 先对它做 filepath.Base——../../etc/passwd → passwd,/etc/passwd → passwd,a/b/c.txt → c.txt;但反斜杠在 Unix 上不是分隔符,..\\..\\win.ini 和 C:\\Users\\x\\a.txt 原样保留(如果服务器跑在 Windows 上就是路径);\"..\" 和 \".\" 也原样保留;带 NUL 的文件名在解析 MIME 头时就被拒绝(400);前后空格保留。", t=tl(S(3)), mark=lidx(S(3), 'win.ini', 'C:', '服务端读到 ".."', '服务端读到 "."'), done=lidx(S(3), '"../../etc/passwd"', '"/etc/passwd"', '"a/b/c.txt"'), kv=KV([['Go 的处理', '先 filepath.Base,去掉目录部分'], ['反斜杠', 'Unix 上不处理,原样保留'], ['".." / "."', '原样保留']], ['反斜杠'])),
    step("SaveUploadedFile(v1.12):先 MkdirAll(目录, 0750),再对这个目录 Chmod(目录, 0750),然后创建文件复制内容。已存在的目录权限被改掉:保存前 exist 是 drwxr-xr-x,保存后 drwxr-x---;新建的 new 与 new/deep 都是 drwxr-x---;传了 perm 0700 的 perm 目录是 drwx------。", t=tl(S(4)), mark=lidx(S(4), 'os.Chmod(dir, mode)', '保存之后 exist 目录权限'), done=lidx(S(4), 'os.MkdirAll(dir, mode)', '保存之前 exist 目录权限', 'b.txt 内容长度'), kv=KV([['MkdirAll', '自动建多级目录,权限 0750'], ['Chmod', '已存在目录的权限也被改成 0750'], ['perm 参数', '可覆盖默认的 0750']], ['Chmod'])),
    step("一个请求里的 part 数量上限:999、1000 个文件都成功;1001 个报 400 multipart: message too large——这是 Go 标准库 mime/multipart 的限制(formdata.go 第 53 行 maxParts := 1000,可用 GODEBUG multipartmaxparts 调整),不是 Gin 的。", t=tl(S(5)), mark=lidx(S(5), '1001 个文件'), done=lidx(S(5), '999 个文件', '1000 个文件'), b=bars([['999 个文件', 999, '成功'], ['1000 个文件', 1000, '成功'], ['1001 个文件', 1001, '400 message too large']], 1001, done=[0, 1], mark=[2]), kv=KV([['上限', '1000 个 part'], ['超过', '400 multipart: message too large'], ['来源', 'Go 标准库,与 Gin 无关']], ['来源'])),
]
A = mkartn('n34', 34, 'Gin,文件上传,多文件,SaveUploadedFile,multipart,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测多文件上传:FormFile 只返回同名字段的第一个文件,MultipartForm().File 返回全部;[]*multipart.FileHeader 可绑定到结构体;文件名先经 filepath.Base 但反斜杠原样保留;SaveUploadedFile 会 MkdirAll 并把已有目录 chmod 成 0750;一个请求最多 1000 个 part。',
    '一次上传好几个文件,该用 FormFile 还是 MultipartForm?怎么绑定到结构体?客户端给的文件名能不能直接用来保存?SaveUploadedFile 会对目录做什么?这篇用真实的 multipart 请求把这些问题一一实测。',
    [('b.txt', 'c.FormFile("files") 对 3 个同名文件返回的那一个(第一个)'), ('..\\..\\win.ini', '反斜杠的文件名在 Unix 上原样保留,不会被 filepath.Base 处理'), ('1000 → 1001', '一个请求最多 1000 个 part,第 1001 个报 multipart: message too large')],
    [('FormFile 与 MultipartForm', '<p><code>FormFile(name)</code> 只能拿到该字段的第一个文件;要全部文件用 <code>MultipartForm()</code> 再取 <code>File[name]</code>,顺序与请求一致。每个 <code>FileHeader</code> 带文件名、大小和原始的 part 头(包含客户端声明的 Content-Type,不可信)。</p>'),
     ('绑定到结构体', '<p>表单绑定认识 <code>*multipart.FileHeader</code> 和 <code>[]*multipart.FileHeader</code> 两种字段类型,和普通字段、<code>binding</code> 校验标签一起工作。只上传一个文件时切片字段长度为 1,不会变成 nil。</p>'),
     ('客户端文件名不可信', '<p>Go 在解析时先对文件名做 <code>filepath.Base</code>,所以 <code>../../etc/passwd</code> 只剩 <code>passwd</code>。但这是按服务器平台的规则:在 Unix 上反斜杠不是分隔符,<code>..\\..\\win.ini</code> 原样保留;<code>..</code>、<code>.</code> 也原样保留。保存文件时最稳妥的做法是不用客户端的文件名,自己生成(如 UUID + 白名单扩展名)。</p>'),
     ('SaveUploadedFile 的副作用', '<p>它先 <code>MkdirAll</code> 创建多级目录,再对目标目录 <code>Chmod</code>(默认 0750)。已经存在的目录权限会被悄悄收紧——保存到一个 0755 的共享目录,之后这个目录对其它用户不可读了。需要不同权限时给它传 <code>perm</code> 参数,或者自己创建目录再保存。</p>'),
     ('part 数量上限', '<p>一个 multipart 请求最多 1000 个 part(包括普通字段),超过时 <code>multipart: message too large</code>。这是 Go 标准库的限制,可以用环境变量 <code>GODEBUG=multipartmaxparts=…</code> 调整(本文没有验证调整)。</p>')],
    steps,
    [ENV_N_GIN + '。用真实的 httptest.NewServer 与手工构造的 multipart 请求;文件内容是占位字节;SaveUploadedFile 的目录在临时目录里,实验后删除;每种情形各一次',
     '读过的 Go 源码:mime/multipart/formdata.go(maxParts 默认 1000);没有验证:Windows 服务器上的文件名处理;GODEBUG=multipartmaxparts 的调整;上传文件的内容类型嗅探(http.DetectContentType);SaveUploadedFile 在符号链接目录下的行为;并发保存同名文件的竞争'],
    '多文件上传')
